HTML_CONTENT = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n  <meta name="theme-color" content="#f9f9f7" id="themeMeta">\n  <title>ClearPix — Cross-Platform AI Photo Enhancer | Rahulprasad Veeramani</title>\n  <meta name="description" content="Enhance photos on any device with AI-powered Real-ESRGAN upscaling. Works across Android, iPhone, Windows, and macOS browsers with 2× and 4× super-resolution.">\n  <link rel="canonical" href="{{ request.base_url }}">\n  <meta name="author" content="Rahulprasad Veeramani">\n\n  <!-- Social & Open Graph Metadata -->\n  <meta property="og:type" content="website">\n  <meta property="og:title" content="ClearPix — Cross-Platform AI Photo Enhancer | Rahulprasad Veeramani">\n  <meta property="og:description" content="Enhance photos on any device with AI-powered Real-ESRGAN upscaling. Works across Android, iPhone, Windows, and macOS browsers with 2× and 4× super-resolution.">\n  <meta property="og:url" content="{{ request.base_url }}">\n  <meta property="og:site_name" content="ClearPix AI Photo Enhancer">\n  <meta property="og:image" content="{{ request.base_url }}static/og-preview.png">\n  <meta property="og:image:width" content="1200">\n  <meta property="og:image:height" content="630">\n  <meta property="og:image:alt" content="ClearPix Cross-Platform AI Photo Enhancer by Rahulprasad Veeramani">\n  \n  <meta name="twitter:card" content="summary_large_image">\n  <meta name="twitter:title" content="ClearPix — Cross-Platform AI Photo Enhancer | Rahulprasad Veeramani">\n  <meta name="twitter:description" content="Use ClearPix on your phone, tablet, or computer. Upload a photo, enhance it with AI, and download the result.">\n  <meta name="twitter:image" content="{{ request.base_url }}static/og-preview.png">\n\n  <!-- Favicon (SVG Brand Mark) -->\n  <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 32 32\'%3E%3Crect width=\'32\' height=\'32\' rx=\'8\' fill=\'%23161814\'/%3E%3Ctext x=\'50%25\' y=\'55%25\' font-size=\'22\' font-weight=\'bold\' fill=\'%23bbf444\' text-anchor=\'middle\' dominant-baseline=\'central\'%3E✳%3C/text%3E%3C/svg%3E">\n\n  <!-- Structured Data: Person & WebApplication (JSON-LD) -->\n  <script type="application/ld+json">\n  {\n    "@context": "https://schema.org",\n    "@graph": [\n      {\n        "@type": "Person",\n        "@id": "{{ request.base_url }}#creator",\n        "name": "Rahulprasad Veeramani",\n        "jobTitle": "Branch Head (India)",\n        "worksFor": {\n          "@type": "Organization",\n          "name": "CyberWolf Team",\n          "url": "https://www.cyberwolf360.in/"\n        },\n        "url": "{{ request.base_url }}",\n        "knowsAbout": [\n          "Artificial Intelligence",\n          "Computer Vision",\n          "Deep Learning",\n          "Image Super-Resolution",\n          "Real-ESRGAN",\n          "Software Engineering"\n        ]\n      },\n      {\n        "@type": "WebApplication",\n        "@id": "{{ request.base_url }}#app",\n        "name": "ClearPix",\n        "alternateName": "ClearPix AI Photo Enhancer",\n        "url": "{{ request.base_url }}",\n        "applicationCategory": "MultimediaApplication",\n        "operatingSystem": "All",\n        "description": "ClearPix is a cross-platform AI photo enhancer and super-resolution upscaler built by Rahulprasad Veeramani, Branch Head (India) @ CyberWolf Team, powered by Real-ESRGAN x4plus. Enhance photos on any device directly in modern web browsers.",\n        "creator": {\n          "@id": "{{ request.base_url }}#creator"\n        },\n        "author": {\n          "@id": "{{ request.base_url }}#creator"\n        },\n        "offers": {\n          "@type": "Offer",\n          "price": "0",\n          "priceCurrency": "USD"\n        }\n      }\n    ]\n  }\n  </script>\n\n  <!-- Prevent Flash of Incorrect Theme (FOUC) -->\n  <script>\n    (function() {\n      try {\n        const stored = localStorage.getItem(\'clearpix-theme\');\n        const systemDark = window.matchMedia(\'(prefers-color-scheme: dark)\').matches;\n        const activeTheme = stored || (systemDark ? \'dark\' : \'light\');\n        document.documentElement.setAttribute(\'data-theme\', activeTheme);\n        const meta = document.getElementById(\'themeMeta\');\n        if (meta) {\n          meta.setAttribute(\'content\', activeTheme === \'dark\' ? \'#0f100e\' : \'#f9f9f7\');\n        }\n      } catch (e) {}\n    })();\n  </script>\n\n  <!-- Modern Typography: Plus Jakarta Sans & Inter -->\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">\n  \n  <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'style.css\') }}?v=4.0">\n</head>\n<body>\n  <!-- Ambient 3D Animated Background Lighting -->\n  <div class="ambient-backdrop" aria-hidden="true">\n    <div class="ambient-orb orb-1"></div>\n    <div class="ambient-orb orb-2"></div>\n    <div class="ambient-grid"></div>\n  </div>\n\n  <!-- 1. Top Navigation Bar -->\n  <header class="topbar">\n    <div class="topbar-inner">\n      <div class="brand-group">\n        <a class="brand" href="/" aria-label="ClearPix Home">\n          <span class="brand-mark">✳</span>\n          <span class="brand-text">ClearPix<span class="dot">.</span></span>\n        </a>\n        <span class="brand-descriptor">AI Photo Enhancer</span>\n      </div>\n\n      <nav class="nav-links">\n        <a href="#workspace" class="nav-link active">Enhance</a>\n        <a href="#howItWorks" class="nav-link">How it works</a>\n        <a href="#how" class="nav-link">Architecture</a>\n        <a href="#creator" class="nav-link">Creator</a>\n        <a href="#faq" class="nav-link">FAQ</a>\n        \n        <div class="privacy-pill" id="deviceBadge" title="Neural image super-resolution powered by Real-ESRGAN x4plus">\n          <span class="green-dot"></span>\n          <span id="deviceText">Real-ESRGAN x4plus · AI Engine</span>\n        </div>\n\n        <!-- Accessible Dark/Light Theme Switcher -->\n        <button type="button" id="themeToggleBtn" class="theme-toggle-btn" aria-label="Toggle dark and light mode" title="Toggle theme">\n          <span class="theme-icon sun-icon" aria-hidden="true">☀️</span>\n          <span class="theme-icon moon-icon" aria-hidden="true">🌙</span>\n        </button>\n      </nav>\n    </div>\n  </header>\n\n  <main class="main-container">\n    <div class="content-container">\n      <!-- 2. Hero Section -->\n      <section class="hero-section">\n        <div class="trust-pill">\n          <span class="sparkle">✦</span> AI-POWERED IMAGE ENHANCEMENT · WORKS ACROSS DEVICES\n        </div>\n        <h1 class="hero-headline">Enhance photos on any device,<br><span>pixel-perfect clarity.</span></h1>\n        <p class="hero-subtext">Use ClearPix on your phone, tablet, or computer. Upload a photo, enhance it with AI, and download the result. Tested and supported on Android, iPhone, Windows, macOS, and modern browsers.</p>\n      </section>\n\n      <!-- 3. Workspace (Uploader, Config, Processing, Comparison) -->\n      <section class="workspace" id="workspace" aria-label="AI Image Upscaler Workspace">\n        \n        <!-- State 1: Dropzone Upload State -->\n        <div id="dropzone" class="dropzone" tabindex="0" role="button" aria-label="Choose an image or drop one here">\n          <input id="fileInput" type="file" accept="image/png,image/jpeg,image/webp" hidden style="display:none !important;">\n          \n          <div class="upload-icon-wrap">\n            <svg class="upload-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">\n              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>\n              <polyline points="17 8 12 3 7 8"></polyline>\n              <line x1="12" y1="3" x2="12" y2="15"></line>\n            </svg>\n          </div>\n\n          <h2 class="dropzone-title">Drag & drop your photo here</h2>\n          <p class="dropzone-or">or</p>\n          \n          <button type="button" id="browseBtn" class="primary-btn browse-btn">\n            <span>Choose an image</span>\n          </button>\n\n          <div class="dropzone-specs">\n            <span class="spec-chip">JPG, PNG or WebP</span>\n            <span class="spec-divider">·</span>\n            <span class="spec-chip">Up to 25 MB</span>\n            <span class="spec-divider">·</span>\n            <span class="spec-chip">Up to 16 MP</span>\n          </div>\n        </div>\n\n        <!-- State 2: Configuration & Enhancement State -->\n        <div id="configCard" class="config-card hidden">\n          <div class="config-header">\n            <div class="file-details">\n              <div class="thumb-frame">\n                <img id="configThumbnail" class="config-thumbnail" src="" alt="Thumbnail preview">\n              </div>\n              <div class="file-meta-group">\n                <strong id="configFileName">photo.jpg</strong>\n                <p id="configFileMeta">2054 × 766 px · 1.8 MB</p>\n              </div>\n            </div>\n            <button id="cancelSelectBtn" class="quiet-btn" type="button">Change image</button>\n          </div>\n\n          <div class="config-body">\n            <div class="scale-section">\n              <div class="section-title-wrap">\n                <label class="scale-label">Super-Resolution Scale</label>\n                <span class="scale-note">Deep neural network upscaling</span>\n              </div>\n              <div class="scale-selector" role="radiogroup" aria-label="Select upscaling scale">\n                <button type="button" class="scale-pill" data-scale="2" role="radio" aria-checked="false">\n                  <span class="scale-num">2×</span>\n                  <span class="scale-desc">Sharper Details</span>\n                </button>\n                <button type="button" class="scale-pill active" data-scale="4" role="radio" aria-checked="true">\n                  <span class="scale-num">4×</span>\n                  <span class="scale-desc">Maximum AI Reconstruction</span>\n                </button>\n              </div>\n            </div>\n\n            <div class="target-meta">\n              <span>Estimated output: <strong id="configOutputMeta">8216 × 3064 px</strong></span>\n            </div>\n\n            <!-- Error Alert Banner -->\n            <div id="errorBanner" class="error-banner hidden" role="alert">\n              <div class="error-content">\n                <span class="error-icon">⚠️</span>\n                <span id="errorMessage">An error occurred during enhancement.</span>\n              </div>\n              <button type="button" id="retryBtn" class="quiet-btn retry-btn">Retry</button>\n            </div>\n\n            <!-- Progress Bar & Honest Status Stages -->\n            <div id="progressWrap" class="progress-wrap hidden">\n              <div class="progress-bar-track">\n                <div id="progressBar" class="progress-bar-fill"></div>\n              </div>\n              <div class="progress-info">\n                <p id="progressStatus" class="progress-status" role="status">Preparing AI model...</p>\n                <span id="elapsedTimer" class="elapsed-timer">0s</span>\n              </div>\n              <!-- Honest Status Stages -->\n              <div class="progress-stages" id="progressStages" aria-label="Inference execution stages">\n                <span class="stage-step" id="stage1">1. Validation</span>\n                <span class="stage-step" id="stage2">2. Model Dispatch</span>\n                <span class="stage-step" id="stage3">3. Super-Resolution</span>\n                <span class="stage-step" id="stage4">4. Tile Assembly</span>\n                <span class="stage-step" id="stage5">5. PNG Encoding</span>\n              </div>\n            </div>\n\n            <div class="config-actions">\n              <button id="cancelEnhanceBtn" class="quiet-btn cancel-enhance-btn hidden" type="button">Cancel</button>\n              <button id="enhanceBtn" class="primary-btn enhance-btn" type="button">\n                <span class="btn-spinner hidden" id="btnSpinner"></span>\n                <span id="btnText">Enhance image</span>\n                <span class="btn-sparkle">✦</span>\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- State 3: Dedicated 3D AI Super-Resolution Loading Screen -->\n        <div id="processingScreen" class="processing-screen hidden" aria-live="polite" aria-label="AI Super-Resolution Processing">\n          <div class="processing-card">\n            <!-- 3D Geometric Ring & Floating Glass Orb Scene -->\n            <div class="gyro-scene" aria-hidden="true">\n              <div class="gyro-ring ring-outer"></div>\n              <div class="gyro-ring ring-middle"></div>\n              <div class="gyro-ring ring-inner"></div>\n              \n              <div class="glass-orb">\n                <div class="orb-highlight"></div>\n                <div class="orb-core">\n                  <span class="orb-mark">✳</span>\n                </div>\n              </div>\n\n              <!-- Floating Micro-Particles -->\n              <div class="particles-field">\n                <span class="particle p1"></span>\n                <span class="particle p2"></span>\n                <span class="particle p3"></span>\n                <span class="particle p4"></span>\n                <span class="particle p5"></span>\n                <span class="particle p6"></span>\n                <span class="particle p7"></span>\n                <span class="particle p8"></span>\n              </div>\n            </div>\n\n            <!-- Hologram Image Scanning Reconstruction Effect -->\n            <div class="hologram-scan-stage">\n              <div class="hologram-frame">\n                <img id="procHologramImg" class="hologram-img" src="" alt="Neural reconstruction preview">\n                <div class="scan-beam"></div>\n                <div class="scan-grid-overlay"></div>\n                <div class="scan-glow-line"></div>\n              </div>\n            </div>\n\n            <!-- Processing Status & Metrics -->\n            <div class="processing-meta-wrap">\n              <div class="proc-brand-line">\n                <span class="proc-brand-text">✳ ClearPix<span class="dot">.</span></span>\n                <span class="proc-device-pill" id="procDeviceText">Real-ESRGAN · MPS</span>\n              </div>\n\n              <h3 class="proc-title" id="procStatusTitle">Preparing your image</h3>\n              <p class="proc-desc" id="procStatusDesc">Validating dimensions and tensor memory allocation...</p>\n\n              <!-- Sleek Animated Indeterminate Progress Rail -->\n              <div class="proc-rail-track" role="progressbar" aria-label="Neural inference progress">\n                <div class="proc-rail-bar"></div>\n              </div>\n\n              <!-- Elapsed Timer & Scale Badge -->\n              <div class="proc-stats-row">\n                <div class="proc-timer">\n                  <span class="timer-live-dot"></span>\n                  <span>Elapsed: <strong id="procTimerVal">0.0s</strong></span>\n                </div>\n                <div class="proc-target-scale">\n                  <span id="procScaleText">4× Super-Resolution</span>\n                </div>\n              </div>\n\n              <!-- Actual Processing Stages Strip -->\n              <div class="proc-stages-grid" id="procStagesGrid">\n                <div class="proc-step active" id="pStage1">\n                  <span class="step-num">1</span>\n                  <span class="step-label">Preparing image</span>\n                </div>\n                <div class="proc-step" id="pStage2">\n                  <span class="step-num">2</span>\n                  <span class="step-label">Loading AI model</span>\n                </div>\n                <div class="proc-step" id="pStage3">\n                  <span class="step-num">3</span>\n                  <span class="step-label">Real-ESRGAN inference</span>\n                </div>\n                <div class="proc-step" id="pStage4">\n                  <span class="step-num">4</span>\n                  <span class="step-label">Reconstructing details</span>\n                </div>\n                <div class="proc-step" id="pStage5">\n                  <span class="step-num">5</span>\n                  <span class="step-label">Preparing enhanced image</span>\n                </div>\n              </div>\n\n              <div class="proc-actions">\n                <button type="button" id="procCancelBtn" class="proc-cancel-btn">\n                  <span>Cancel processing</span>\n                </button>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- State 4: Comparison Workspace (Result) -->\n        <div id="editor" class="editor hidden">\n          <div class="editor-head">\n            <div class="editor-titles">\n              <strong id="fileName">Image</strong>\n              <p id="dimensions">Original: 2054 × 766 px</p>\n            </div>\n            <button id="resetBtn" class="quiet-btn reset-btn" type="button">Enhance another image</button>\n          </div>\n\n          <div class="preview-stage" id="previewStage">\n            <!-- Floating Zoom & Fit Toolbar -->\n            <div class="zoom-toolbar" role="toolbar" aria-label="Viewer zoom and display controls">\n              <button type="button" id="zoomOutBtn" class="zoom-btn" title="Zoom Out (−)" aria-label="Zoom Out">−</button>\n              <span id="zoomLevel" class="zoom-level">100%</span>\n              <button type="button" id="zoomInBtn" class="zoom-btn" title="Zoom In (+)" aria-label="Zoom In">+</button>\n              <span class="zoom-divider"></span>\n              <button type="button" id="fitScreenBtn" class="zoom-btn zoom-text-btn active" title="Fit to Screen">Fit</button>\n              <button type="button" id="zoom100Btn" class="zoom-btn zoom-text-btn" title="100% Actual Pixels">1:1</button>\n              <button type="button" id="zoom200Btn" class="zoom-btn zoom-text-btn" title="200% Detail Zoom">2× Zoom</button>\n              <span class="zoom-divider"></span>\n              <button type="button" id="fullscreenBtn" class="zoom-btn zoom-icon-btn" title="Toggle Fullscreen (F)" aria-label="Toggle Fullscreen">⛶</button>\n            </div>\n\n            <div class="preview-wrap" id="previewWrap">\n              <!-- Underneath: Original Image -->\n              <img id="previewImage" alt="Original photo preview">\n              \n              <!-- On top: Real-ESRGAN AI Output with clipping mask -->\n              <div id="afterPane" class="after-pane">\n                <img id="upscaledPreview" alt="AI super-resolved photo preview">\n              </div>\n\n              <div class="preview-label before-label">ORIGINAL</div>\n              <div class="preview-label after-label" id="afterBadge">AI ENHANCED 4×</div>\n              \n              <input id="compareSlider" class="compare-slider" type="range" min="0" max="100" value="50" aria-label="Compare original and enhanced photo">\n              <div class="slider-line" id="sliderLine" aria-hidden="true">\n                <span class="slider-knob">↔</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Comprehensive Output Metadata Grid -->\n          <div class="metadata-grid" id="metadataGrid" aria-label="Image enhancement metrics">\n            <div class="meta-item">\n              <span class="meta-label">Original Dimensions</span>\n              <strong class="meta-val" id="metaOriginal">2054 × 766 px</strong>\n            </div>\n            <div class="meta-item">\n              <span class="meta-label">Enhanced Dimensions</span>\n              <strong class="meta-val highlight-val" id="metaEnhanced">8216 × 3064 px</strong>\n            </div>\n            <div class="meta-item">\n              <span class="meta-label">Scale Factor</span>\n              <strong class="meta-val" id="metaScale">4× Real-ESRGAN</strong>\n            </div>\n            <div class="meta-item">\n              <span class="meta-label">Processing Time</span>\n              <strong class="meta-val" id="metaDuration">43.8s</strong>\n            </div>\n            <div class="meta-item">\n              <span class="meta-label">Inference Device</span>\n              <strong class="meta-val" id="metaDevice">Server Accelerator</strong>\n            </div>\n          </div>\n\n          <div class="editor-actions">\n            <div class="scale-info">\n              <span class="green-dot"></span>\n              <span id="outputDimensions">AI Enhanced (8216 × 3064 px)</span>\n            </div>\n            <button id="downloadBtn" class="primary-btn download-btn" type="button">\n              <span>Download PNG</span>\n              <span class="btn-download-arrow">↓</span>\n            </button>\n          </div>\n          <p id="status" class="status" role="status"></p>\n        </div>\n      </section>\n\n      <!-- 4. How It Works 4-Step Interactive Guide -->\n      <section class="how-it-works-section" id="howItWorks">\n        <div class="section-badge">WORKFLOW</div>\n        <h2>How ClearPix enhances your photos.</h2>\n        <div class="steps-grid">\n          <div class="step-card">\n            <div class="step-badge">01</div>\n            <h3>Upload Photo</h3>\n            <p>Upload any JPG, PNG, or WebP photo up to 25 MB and 16 MP. Works across Android, iPhone, Windows, and macOS browsers.</p>\n          </div>\n          <div class="step-card">\n            <div class="step-badge">02</div>\n            <h3>Neural Processing</h3>\n            <p>The image is streamed through the 23-block Residual-in-Residual Dense Network (RRDBNet) with tiled server GPU inference.</p>\n          </div>\n          <div class="step-card">\n            <div class="step-badge">03</div>\n            <h3>Select 2× or 4× Scale</h3>\n            <p>Choose 2× for subtle texture cleaning and sharpening, or 4× for maximum neural detail reconstruction.</p>\n          </div>\n          <div class="step-card">\n            <div class="step-badge">04</div>\n            <h3>Compare & Download</h3>\n            <p>Inspect the result with the interactive split-screen slider, zoom in up to 400%, and download your full-resolution PNG.</p>\n          </div>\n        </div>\n      </section>\n\n      <!-- 5. Architecture & Neural Network Engine -->\n      <section class="benefits" id="how">\n        <article class="benefit-card">\n          <div class="benefit-icon">🧠</div>\n          <h3>Official RRDBNet Architecture</h3>\n          <p>Uses the official 23-block Residual-in-Residual Dense Network trained on high-order realistic degradations to synthesize authentic photographic textures rather than blurry interpolation.</p>\n        </article>\n        <article class="benefit-card">\n          <div class="benefit-icon">⚡</div>\n          <h3>Cross-Platform Acceleration</h3>\n          <p>Accelerated via optimized PyTorch tensor inference with streaming tiled execution, processing multi-megapixel images rapidly on server hardware without client memory thrashing.</p>\n        </article>\n        <article class="benefit-card">\n          <div class="benefit-icon">🔒</div>\n          <h3>Private & Temporary Storage</h3>\n          <p>Photos are processed securely on our server. Images are assigned random UUID filenames, kept in temporary storage, automatically deleted after 1 hour, and never shared or retained.</p>\n        </article>\n      </section>\n\n      <!-- 6. Honest Capabilities & Limitations Notice -->\n      <section class="disclaimer-section">\n        <div class="disclaimer-card">\n          <div class="disclaimer-icon">ℹ️</div>\n          <div class="disclaimer-text">\n            <h4>Important Note on Neural Super-Resolution</h4>\n            <p>Real-ESRGAN dramatically improves perceived sharpness, eliminates compression artifacts, and reconstructs fine natural textures using deep learning. However, it cannot guarantee recovery of true microscopic optical information that was never recorded by the physical camera sensor.</p>\n          </div>\n        </div>\n      </section>\n\n      <!-- 7. About Section -->\n      <section class="about-section" id="about">\n        <div class="section-badge">ABOUT CLEARPIX</div>\n        <h2>Designed for photographers & creators.</h2>\n        <div class="about-grid">\n          <div class="about-col">\n            <h4>True Neural Reconstruction</h4>\n            <p>Traditional image upscaling tools rely on bicubic or Lanczos resampling, which only mathematically blur existing pixels. ClearPix runs deep convolutional neural networks that hallucinate realistic micro-details, restore edges, and clean compression noise.</p>\n          </div>\n          <div class="about-col">\n            <h4>Privacy-First Architecture</h4>\n            <p>ClearPix processes images on our secure self-hosted server. Images are never stored in public directories, shared with third-party cloud APIs, or used for model training. Once processed, temporary files are automatically purged after 1 hour.</p>\n          </div>\n        </div>\n      </section>\n\n      <!-- 8. About the Creator Section -->\n      <section class="creator-section" id="creator" aria-labelledby="creator-heading">\n        <div class="section-badge">LEADERSHIP & ENGINEERING</div>\n        <h2 id="creator-heading">About the Creator</h2>\n        <div class="creator-card">\n          <div class="creator-avatar" aria-hidden="true">\n            <span class="creator-initials">RV</span>\n          </div>\n          <div class="creator-content">\n            <div class="creator-header">\n              <h3 class="creator-name">Rahulprasad Veeramani</h3>\n              <p class="creator-role-line"><strong class="title-bold">Branch Head (India)</strong> @ <a href="https://www.cyberwolf360.in/" target="_blank" rel="noopener noreferrer" class="cyberwolf-inline-link" title="CyberWolf Team Official Website">CyberWolf Team <span class="external-icon" aria-hidden="true">↗</span></a></p>\n            </div>\n            <p class="creator-bio">\n              Rahulprasad Veeramani is the Branch Head (India) at CyberWolf Team, focusing on computer vision systems, applied machine learning, and high-performance software engineering. ClearPix AI Photo Enhancer was designed and developed to provide photographers and creators with an accessible, high-performance photo upscaling tool powered by the 23-block RRDBNet neural architecture, running across modern desktop and mobile browsers.\n            </p>\n            <div class="creator-actions">\n              <a href="https://www.cyberwolf360.in/" target="_blank" rel="noopener noreferrer" class="creator-btn" title="Visit CyberWolf Team official website (opens in a new tab)">\n                <span>CyberWolf Team</span>\n                <span class="external-icon" aria-hidden="true">↗</span>\n              </a>\n              <a href="#workspace" class="creator-btn creator-btn-primary" title="Enhance your photo with ClearPix">\n                <span>Enhance a Photo</span>\n                <span>↑</span>\n              </a>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 9. FAQ Section -->\n      <section class="how-section" id="faq">\n        <div class="eyebrow">FREQUENTLY ASKED QUESTIONS</div>\n        <h2>Everything you need to know.</h2>\n        \n        <details>\n          <summary>What is Real-ESRGAN x4plus?</summary>\n          <p>Real-ESRGAN is an advanced blind super-resolution model developed by ARC Lab at Tencent PCG and Shenzhen Institutes of Advanced Technology. It models complex combinations of blur, noise, downsampling, and JPEG compression to reconstruct clean, high-resolution photographs.</p>\n        </details>\n        \n        <details>\n          <summary>Can I use ClearPix on mobile and desktop devices?</summary>\n          <p>Yes. ClearPix is fully responsive and works on Android, iPhone, iPad, Windows, macOS, and Linux across all modern browsers (Chrome, Safari, Firefox, Edge). AI enhancement is executed on the server, so you get high-quality super-resolution on any device regardless of your client hardware.</p>\n        </details>\n\n        <details>\n          <summary>How does server-side AI processing work?</summary>\n          <p>When you upload a photo, it is received securely by our backend server and passed through the pretrained Real-ESRGAN x4plus neural network. The server uses hardware acceleration (such as GPU tensor acceleration or high-throughput CPU inference) to synthesize fine details, returning a crisp, high-resolution PNG to your browser.</p>\n        </details>\n        \n        <details>\n          <summary>How are large images handled?</summary>\n          <p>Large panoramic and high-megapixel photos are divided into 512×512 tiles with overlapping padding. Completed tiles stream directly to CPU memory, preventing unified VRAM thrashing and eliminating seam artifacts.</p>\n        </details>\n\n        <details>\n          <summary>Are my uploaded photos private?</summary>\n          <p>Yes. Images uploaded to ClearPix are stored temporarily on the server solely to generate your enhanced preview and download. Files are saved with random UUID filenames in a private temporary directory and automatically deleted after 1 hour. Images are never sold, never shared with third parties, and never used to train AI models. See our <a href="/privacy" class="cyberwolf-inline-link">Privacy Policy</a> for full details.</p>\n        </details>\n      </section>\n    </div>\n  </main>\n\n  <!-- 10. Footer with Professional Attribution -->\n  <footer class="footer">\n    <div class="footer-inner">\n      <div class="footer-brand">\n        <a class="brand" href="/">\n          <span class="brand-mark">✳</span>\n          <span class="brand-text">ClearPix<span class="dot">.</span></span>\n        </a>\n        <p class="footer-desc">Cross-platform AI photo super-resolution powered by Real-ESRGAN x4plus. Enhance photos on any device with genuine neural reconstruction.</p>\n        \n        <!-- Personal Attribution -->\n        <div class="footer-attribution" aria-label="Author and team attribution">\n          <p class="attribution-author">Made by <strong>Rahulprasad Veeramani</strong></p>\n          <p class="attribution-team"><strong class="title-bold">Branch Head (India)</strong> @ <a href="https://www.cyberwolf360.in/" target="_blank" rel="noopener noreferrer" class="cyberwolf-link" title="Visit CyberWolf Team official website (opens in a new tab)"><strong>CyberWolf Team</strong><span class="external-icon" aria-hidden="true">↗</span></a></p>\n        </div>\n      </div>\n\n      <div class="footer-links-group">\n        <div class="footer-col">\n          <h5>Application</h5>\n          <a href="#workspace">Enhance Photo</a>\n          <a href="#howItWorks">How it works</a>\n          <a href="#how">Architecture</a>\n          <a href="#creator">About the Creator</a>\n          <a href="#faq">FAQ</a>\n          <a href="/privacy">Privacy Policy</a>\n        </div>\n        <div class="footer-col">\n          <h5>Technology</h5>\n          <span>Real-ESRGAN x4plus</span>\n          <span>Hardware Accelerated</span>\n          <span>PyTorch Neural Net</span>\n        </div>\n      </div>\n    </div>\n    <div class="footer-bottom">\n      <p>© 2026 ClearPix AI · <a href="/privacy" class="cyberwolf-inline-link">Privacy Policy</a> · Zero third-party telemetry.</p>\n    </div>\n  </footer>\n\n  <script src="{{ url_for(\'static\', filename=\'app.js\') }}?v=4.0"></script>\n</body>\n</html>\n'
